export const nationById = (id: string) => NATIONS.find((n) => n.id === id);

export const placeName = (id: string) => (id in PLACES ? PLACES[id as keyof typeof PLACES] : nationById(id)!.name);

/** The point on land (or sea) where news about a nation or place is pinned. */
export function anchor(id: string): [number, number] {
  if (id in MAP.places) return MAP.places[id as keyof typeof MAP.places].at as [number, number];
  const l = MAP.labels[id as keyof typeof MAP.labels] as { at: number[]; from?: number[] };
  return (l.from ?? l.at) as [number, number];
}

export interface MapDot {
  id: number;
  at: [number, number];
  tone: 'conflict' | 'calm' | 'econ';
  /** fresh: just landed (rippling) · old: unread for a while (dimmed) · leaving: read, fading out. */
  state: 'fresh' | '' | 'old' | 'leaving';
}

export type Light = 'red' | 'amber' | 'green';
const STATE: Record<Light, string> = { red: 'conflict', amber: 'tense', green: 'easing' };

